# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ALLAHÜMME SALLİ VE ALLAHÜMME BARİK DUALARI</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Allahümme Salli Duası ve Anlamı</text>\n  <text x="50" y="106" font-size="11" fill="#1e293b">Allâhümme salli alâ Muhammedin ve alâ âli</text>\n  <text x="50" y="124" font-size="11" fill="#1e293b">Muhammed. Kemâ salleyte alâ İbrâhîme ve alâ</text>\n  <text x="50" y="142" font-size="11" fill="#1e293b">âli İbrâhîm. İnneke hamîdün mecîd.</text>\n  <text x="50" y="170" font-size="11" fill="#334155">Anlamı: Allah\'ım! Hz. İbrahim\'e ve ailesine</text>\n  <text x="50" y="187" font-size="11" fill="#334155">rahmet ettiğin gibi Hz. Muhammed\'e ve ailesine</text>\n  <text x="50" y="204" font-size="11" fill="#334155">de rahmet eyle. Şüphesiz Sen Hamîd ve Mecîd\'sin.</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Allahümme Barik Duası ve Anlamı</text>\n  <text x="375" y="106" font-size="11" fill="#1e293b">Allâhümme bârik alâ Muhammedin ve alâ âli</text>\n  <text x="375" y="124" font-size="11" fill="#1e293b">Muhammed. Kemâ bârekte alâ İbrâhîme ve alâ</text>\n  <text x="375" y="142" font-size="11" fill="#1e293b">âli İbrâhîm. İnneke hamîdün mecîd.</text>\n  <text x="375" y="170" font-size="11" fill="#334155">Anlamı: Allah\'ım! Hz. İbrahim\'i ve ailesini</text>\n  <text x="375" y="187" font-size="11" fill="#334155">mübarek kıldığın gibi Hz. Muhammed\'i ve ailesini</text>\n  <text x="375" y="204" font-size="11" fill="#334155">de mübarek kıl. Şüphesiz Sen Hamîd ve Mecîd\'sin.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SALAVAT KAVRAMLARI VE OKUNDUĞU YERLER</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Dualardaki Temel Kavramlar</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Salât (Salli): Rahmet, esenlik ve hayır duası</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• Bârik: Bereketli ve mübarek kılmak</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• Âl: Peygamberimizin ailesi, ev halkı ve</text>\n  <text x="65" y="173" font-size="11" fill="#475569">onun yolundan giden müminler</text>\n  <text x="55" y="198" font-size="11.5" font-weight="bold" fill="#854d0e">• Hamîd: Çok övülen • Mecîd: Şanı yüce</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Nerelerde Okunur?</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Bütün namazların son oturuşunda (Ka\'de-i</text>\n  <text x="390" y="125" font-size="11" fill="#475569">âhire) Ettehiyyâtü duasından hemen sonra</text>\n  <text x="380" y="150" font-size="11.5" fill="#334155">• İkindi ve yatsı namazlarının ilk sünneti ile</text>\n  <text x="390" y="167" font-size="11" fill="#475569">teravih namazının ilk oturuşunda</text>\n  <text x="380" y="192" font-size="11.5" fill="#334155">• Cenaze namazında 2. tekbirden sonra</text>\n  <text x="380" y="214" font-size="11" font-weight="bold" fill="#1e40af">• Peygamberimizin ismi anıldığında (Salavat)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. TEMA DEĞERLENDİRMESİ: KUR\'AN-I KERİM\'İN İÇ DÜZENİ</text>\n  <rect x="35" y="60" width="145" height="165" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="107" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ayet (6236)</text>\n  <text x="107" y="115" text-anchor="middle" font-size="11" fill="#334155">Sureleri oluşturan</text>\n  <text x="107" y="133" text-anchor="middle" font-size="11" fill="#334155">cümlelerdir.</text>\n  <text x="107" y="155" text-anchor="middle" font-size="11" fill="#334155">En uzun ayet:</text>\n  <text x="107" y="173" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Müdâyene (Bakara 282)</text>\n  <rect x="200" y="60" width="145" height="165" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="272" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Sure (114)</text>\n  <text x="272" y="115" text-anchor="middle" font-size="11" fill="#334155">Ayetlerden oluşan</text>\n  <text x="272" y="133" text-anchor="middle" font-size="11" fill="#334155">bölümlerdir.</text>\n  <text x="272" y="155" text-anchor="middle" font-size="11" fill="#334155">İlk: Fatiha • Son: Nas</text>\n  <text x="272" y="173" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">En uzun: Bakara (286)</text>\n  <text x="272" y="191" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">En kısa: Kevser (3)</text>\n  <rect x="365" y="60" width="145" height="165" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="437" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Cüz (30)</text>\n  <text x="437" y="115" text-anchor="middle" font-size="11" fill="#334155">20 sayfadan oluşan</text>\n  <text x="437" y="133" text-anchor="middle" font-size="11" fill="#334155">30 eşit bölümdür.</text>\n  <text x="437" y="155" text-anchor="middle" font-size="11" fill="#334155">Mushaf toplam</text>\n  <text x="437" y="173" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">600 sayfadır.</text>\n  <rect x="530" y="60" width="140" height="165" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="600" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Hizip (120)</text>\n  <text x="600" y="115" text-anchor="middle" font-size="11" fill="#334155">Her cüzün 4\'e</text>\n  <text x="600" y="133" text-anchor="middle" font-size="11" fill="#334155">bölünmesiyle oluşan</text>\n  <text x="600" y="151" text-anchor="middle" font-size="11" fill="#334155">5 sayfalık kısımdır.</text>\n  <text x="600" y="173" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">30 × 4 = 120 Hizip</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
